      "name": "MvPolynomial.totalDegree_monomial_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (s : σ →₀ ℕ) (c : R),\n  ((MvPolynomial.monomial s) c).totalDegree ≤ s.sum fun x => id"
    },
    {
      "name": "Polynomial.hasseDeriv_apply",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (k : ℕ) (f : Polynomial R),\n  (Polynomial.hasseDeriv k) f = f.sum fun i r => (Polynomial.monomial (i - k)) (↑(i.choose k) * r)"
    },
    {
      "name": "LaurentSeries.hasseDeriv_coeff",
      "module_name": "Mathlib.RingTheory.LaurentSeries",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] {V : Type u_2} [inst_1 : AddCommGroup V] [inst_2 : Module R V] (k : ℕ)\n  (f : LaurentSeries V) (n : ℤ), ((LaurentSeries.hasseDeriv R k) f).coeff n = Ring.choose (n + ↑k) k • f.coeff (n + ↑k)"
    },
    {
      "name": "Polynomial.natDegree_hasseDeriv_le",
      "module_name": "Mathlib.Algebra.Polynomial.HasseDeriv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] (p : Polynomial R) (n : ℕ),\n  ((Polynomial.hasseDeriv n) p).natDegree ≤ p.natDegree - n"
    },
    {
      "name": "Polynomial.coeff_bdd_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {B : ℝ} {d : ℕ} (f : F →+* K)\n  {p : Polynomial F},\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      p.natDegree ≤ d →\n        (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n          ∀ (i : ℕ), ‖(Polynomial.map f p).coeff i‖ ≤ max B 1 ^ d * ↑(d.choose (d / 2))"
    }
  ]
}

